+    def get_blame_for_file(
+        self, repo: Repository, path: str, ref: str
+    ) -> Sequence[Mapping[str, Any]]:
+        [owner, name] = repo.name.split("/")
+        query = f"""query {{
+            repository(name: {name}, owner: {owner}) {{
+                ref(qualifiedName: {ref}) {{
+                    target {{
+                        ... on Commit {{
+                            blame(path: {path}) {{
+                                ranges {{
+                                        commit {{
+                                            oid
+                                            author {{
+                                                name
+                                                email
+                                            }}
+                                            message
+                                        }}
+                                    startingLine
+                                    endingLine
+                                    age
+                                }}
+                            }}
+                        }}
+                    }}
+                }}
+            }}
+        }}"""
+
+        contents = self.post(
+            path="/graphql",
+            data={"query": query},
+        )
+        results: Sequence[Mapping[str, Any]] = (
+            contents.get("data", {})
+            .get("repository", {})
+            .get("ref", {})
+            .get("target", {})
+            .get("blame", [])
+        )
+        return results
+

